class Runner:
    def __init__(self, partitions):
        self.partitions = partitions

    def recursively_apply_fns(self, fns):
        new_callables = []
        for fn, c in zip(fns, self.partitions):
            new_callables.append(fn(c))
        self.partitions = new_callables

    def call(self, args):
        arg0_1, arg1_1, arg2_1, arg3_1 = args
        args.clear()
        # Topologically Sorted Source Nodes: [unsqueeze, w, vecs, transpose, d2], Original ATen: [aten.unsqueeze, aten.select, aten.view, aten.transpose, aten.baddbmm]
        buf0 = torch.ops.aten.baddbmm.default(reinterpret_tensor(arg2_1, (8, 1, 16), (16, 16, 1), 0), reinterpret_tensor(arg0_1, (8, 128, 2), (32768, 256, 128), 0), reinterpret_tensor(arg3_1, (8, 2, 16), (32, 1, 2), 0), alpha=-2.0)
        buf1 = buf0
        assert_size_stride(buf1, (8, 128, 16), (2048, 16, 1), 'torch.ops.aten.baddbmm.default')
        assert_alignment(buf1, 16, 'torch.ops.aten.baddbmm.default')
        # Topologically Sorted Source Nodes: [idx], Original ATen: [aten.argmin]
        buf2 = torch.ops.aten.argmin.default(buf1, -1)
        del buf1
        buf3 = buf2
        assert_size_stride(buf3, (8, 128), (128, 1), 'torch.ops.aten.argmin.default')
        assert_alignment(buf3, 16, 'torch.ops.aten.argmin.default')
        del buf2
