    arg2_1 = rand_strided((8, 16), (16, 1), device='npu:0', dtype=torch.float32)
    arg3_1 = rand_strided((8, 16, 2), (32, 2, 1), device='npu:0', dtype=torch.float32)
    fn = lambda: call([arg0_1, arg1_1, arg2_1, arg3_1])
    return print_performance(fn, times=times, repeat=repeat)


